questionvariables.text:
/*Defining the question*/
aa: rand(3); bb: 1+aa;
func_var_u:expand((x^bb-aa)*(x+bb)); /*this is what will become  u in the question func*/
func_var_dv:e^-(bb*x);  /*varible for dv in the question func*/
question_func:(func_var_u)*((func_var_dv)); /* questoin expression in terms of u \times dv*/

/*model answers*/
ta:expand(int(question_func,x)+c);   /*force simplification of model answer*/

/*Worked out solution codes*/
diff_u:diff(func_var_u)/del(x);    /* derivative of var_u */
int_v: int(func_var_dv,x);    /* integral of dv to get v */
v_du: int_v*diff_u;   /* product  (diff_u and int_v) */
int_v_du: ratsimp(int(v_du,x));    /* integral of _ product  (diff_u and int_v) */

feedbackvariables.text:
/*Node1- checking for correct answer*/

/*Node 2: mistake_ failing to add the constant after integration*/
sans_1:int(question_func,x);

/*Node 3: differentiating instead of integrating*/
sans_2:diff(question_func);
